import{_ as e,o as t,c as r,a2 as a}from"./chunks/framework.DGzjq_gw.js";const p=JSON.parse('{"title":"浏览器与网络高频题","description":"","frontmatter":{},"headers":[],"relativePath":"interview/browser-network-questions.md","filePath":"interview/browser-network-questions.md","lastUpdated":1792470007000}'),d={name:"interview/browser-network-questions.md"};function n(c,o,s,i,l,g){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="浏览器与网络高频题" tabindex="-1">浏览器与网络高频题 <a class="header-anchor" href="#浏览器与网络高频题" aria-label="Permalink to &quot;浏览器与网络高频题&quot;">​</a></h1><p>本页覆盖浏览器原理与网络层的高频题，采用 <strong>[问法] → [要点] → [深度补充]</strong> 结构。对应 JD 要求 A2（浏览器原理）+ B5（HTTP 请求层）+ B8（前端安全，4 份 JD）。</p><blockquote><p>深入阅读：<a href="/frontend-kb-pages/network/http-layer">HTTP 与请求层设计</a>、<a href="/frontend-kb-pages/network/cross-origin">浏览器跨域机制</a>、<a href="/frontend-kb-pages/network/realtime">实时通信 WebSocket/SSE</a>、<a href="/frontend-kb-pages/security/web-security">前端 Web 安全</a>。</p></blockquote><h2 id="一、渲染原理" tabindex="-1">一、渲染原理 <a class="header-anchor" href="#一、渲染原理" aria-label="Permalink to &quot;一、渲染原理&quot;">​</a></h2><h3 id="q1-从输入-url-到页面渲染发生了什么" tabindex="-1">Q1. 从输入 URL 到页面渲染发生了什么？ <a class="header-anchor" href="#q1-从输入-url-到页面渲染发生了什么" aria-label="Permalink to &quot;Q1. 从输入 URL 到页面渲染发生了什么？&quot;">​</a></h3><p><strong>要点</strong>：分阶段——① URL 解析与 DNS 查询；② TCP 三次握手（HTTPS 再加 TLS 握手）；③ 发送 HTTP 请求；④ 服务器响应；⑤ 浏览器解析 HTML 构建 DOM、解析 CSS 构建 CSSOM，合成渲染树；⑥ 布局（layout）计算几何；⑦ 绘制（paint）与合成（composite）；⑧ 执行 JS、加载子资源。</p><p><strong>深度补充</strong>：DNS 有缓存层级（浏览器 → 系统 → 路由器 → ISP）；HTML 解析遇 <code>&lt;script&gt;</code> 会<strong>阻塞解析</strong>（无 <code>defer/async</code> 时），遇 <code>&lt;link&gt;</code> CSS 会阻塞渲染。现代浏览器还会做<strong>预加载扫描</strong>（preload scanner）提前发现子资源。</p><h3 id="q2-浏览器渲染流程与重排、重绘" tabindex="-1">Q2. 浏览器渲染流程与重排、重绘？ <a class="header-anchor" href="#q2-浏览器渲染流程与重排、重绘" aria-label="Permalink to &quot;Q2. 浏览器渲染流程与重排、重绘？&quot;">​</a></h3><p><strong>要点</strong>：渲染流水线——<code>DOM + CSSOM → Render Tree → Layout（重排）→ Paint（重绘）→ Composite（合成）</code>。<strong>重排</strong>改变几何（位置/尺寸），代价最大且会连锁重绘；<strong>重绘</strong>只改外观（颜色/背景），代价较小；<strong>合成</strong>只改 <code>transform/opacity</code>，可由 GPU 独立线程处理、不触发重排重绘。</p><p><strong>深度补充</strong>：优化原则——动画优先用 <code>transform/opacity</code>；用 <code>will-change</code>/<code>translateZ</code> 提升为独立图层；批量读写 DOM 避免<strong>布局抖动</strong>（强制同步布局）；用 <code>DocumentFragment</code> 或离线节点批量更新。<code>display: none</code> 会触发重排，<code>visibility: hidden</code> 只重绘。</p><h3 id="q3-什么会触发强制同步布局-布局抖动" tabindex="-1">Q3. 什么会触发强制同步布局（布局抖动）？ <a class="header-anchor" href="#q3-什么会触发强制同步布局-布局抖动" aria-label="Permalink to &quot;Q3. 什么会触发强制同步布局（布局抖动）？&quot;">​</a></h3><p><strong>要点</strong>：在同一帧里&quot;写 DOM → 立即读布局属性（<code>offsetHeight</code>/<code>getComputedStyle</code>）→ 再写&quot;会强制浏览器提前同步计算布局，反复触发重排。</p><p><strong>深度补充</strong>：修复方法是<strong>先集中读、再集中写</strong>（read-then-write）。<code>requestAnimationFrame</code> 里做视觉更新、<code>requestIdleCallback</code> 做非紧急任务，能避免抖动。使用 <code>FastDOM</code> 之类的批处理库也是常见方案。</p><h2 id="二、http-缓存" tabindex="-1">二、HTTP 缓存 <a class="header-anchor" href="#二、http-缓存" aria-label="Permalink to &quot;二、HTTP 缓存&quot;">​</a></h2><h3 id="q4-强缓存与协商缓存" tabindex="-1">Q4. 强缓存与协商缓存？ <a class="header-anchor" href="#q4-强缓存与协商缓存" aria-label="Permalink to &quot;Q4. 强缓存与协商缓存？&quot;">​</a></h3><p><strong>要点</strong>：<strong>强缓存</strong>由 <code>Cache-Control</code>（<code>max-age</code>）或 <code>Expires</code> 控制，命中后<strong>不发请求</strong>直接用本地缓存；<strong>协商缓存</strong>在强缓存失效后，带 <code>If-None-Match</code>（配 <code>ETag</code>）或 <code>If-Modified-Since</code>（配 <code>Last-Modified</code>）询问服务器，未变则返回 <code>304</code>。</p><p><strong>深度补充</strong>：<code>Cache-Control</code> 优先级高于 <code>Expires</code>（后者是绝对时间、受本地时钟影响）。<code>ETag</code> 比 <code>Last-Modified</code> 更精确（内容哈希，能识别秒内修改），但计算有成本。<code>no-cache</code> 是&quot;要协商&quot;（仍存缓存），<code>no-store</code> 是完全不缓存，别混淆。</p><table tabindex="0"><thead><tr><th>类型</th><th>头</th><th>命中结果</th><th>是否发请求</th></tr></thead><tbody><tr><td>强缓存</td><td><code>Cache-Control: max-age</code> / <code>Expires</code></td><td>200 (from cache)</td><td>否</td></tr><tr><td>协商缓存</td><td><code>ETag</code>+<code>If-None-Match</code> / <code>Last-Modified</code>+<code>If-Modified-Since</code></td><td>304 Not Modified</td><td>是</td></tr></tbody></table><h3 id="q5-前端资源缓存策略怎么设计" tabindex="-1">Q5. 前端资源缓存策略怎么设计？ <a class="header-anchor" href="#q5-前端资源缓存策略怎么设计" aria-label="Permalink to &quot;Q5. 前端资源缓存策略怎么设计？&quot;">​</a></h3><p><strong>要点</strong>：HTML 用 <code>no-cache</code>（每次都协商，保证入口最新）；带哈希的静态资源（<code>app.1a2b3c.js</code>）用 <code>max-age=31536000, immutable</code>（内容变则文件名变，可长期强缓存）。</p><p><strong>深度补充</strong>：<code>immutable</code> 告诉浏览器&quot;过期前不要再发验证请求&quot;。改用文件名哈希而非查询参数（<code>?v=1</code>）——有些 CDN/浏览器对带查询串的资源缓存策略不一致。配合 <code>Service Worker</code> 可做更细粒度的离线缓存。</p><h2 id="三、跨域与安全" tabindex="-1">三、跨域与安全 <a class="header-anchor" href="#三、跨域与安全" aria-label="Permalink to &quot;三、跨域与安全&quot;">​</a></h2><h3 id="q6-什么是同源策略-如何跨域" tabindex="-1">Q6. 什么是同源策略？如何跨域？ <a class="header-anchor" href="#q6-什么是同源策略-如何跨域" aria-label="Permalink to &quot;Q6. 什么是同源策略？如何跨域？&quot;">​</a></h3><p><strong>要点</strong>：同源 = 协议 + 域名 + 端口三者相同。跨域方案：<strong>CORS</strong>（服务端设 <code>Access-Control-Allow-*</code>，主流）、<strong>JSONP</strong>（只支持 GET，已过时）、<strong>代理</strong>（开发用 Vite/Webpack devServer proxy、生产用 Nginx 反代）、<strong>postMessage</strong>（页面间通信）、<strong>WebSocket</strong>（不受同源策略限制）。</p><p><strong>深度补充</strong>：跨域限制的是<strong>读取响应</strong>（XHR/fetch），不是&quot;发送请求&quot;——简单请求会真的发出，只是响应被拦。<code>document.domain</code>（已废弃）、<code>window.name</code>、iframe 跳转是历史方案。</p><h3 id="q7-cors-的简单请求与预检请求" tabindex="-1">Q7. CORS 的简单请求与预检请求？ <a class="header-anchor" href="#q7-cors-的简单请求与预检请求" aria-label="Permalink to &quot;Q7. CORS 的简单请求与预检请求？&quot;">​</a></h3><p><strong>要点</strong>：<strong>简单请求</strong>（GET/HEAD/POST + 特定 Content-Type + 无自定义头）直接发送，响应带 <code>Access-Control-Allow-Origin</code> 即可；<strong>非简单请求</strong>先发 <code>OPTIONS</code> <strong>预检</strong>，服务器返回允许的方法/头后（<code>Access-Control-Allow-Methods</code>/<code>-Headers</code>）才发真实请求。</p><p><strong>深度补充</strong>：带凭证（Cookie）的跨域请求要求 <code>Access-Control-Allow-Credentials: true</code> <strong>且</strong> <code>Access-Control-Allow-Origin</code> 不能是 <code>*</code>（必须是具体来源）。预检结果可用 <code>Access-Control-Max-Age</code> 缓存，减少 OPTIONS 次数。</p><h3 id="q8-跨域下-cookie-为什么带不上-如何解决" tabindex="-1">Q8. 跨域下 Cookie 为什么带不上？如何解决？ <a class="header-anchor" href="#q8-跨域下-cookie-为什么带不上-如何解决" aria-label="Permalink to &quot;Q8. 跨域下 Cookie 为什么带不上？如何解决？&quot;">​</a></h3><p><strong>要点</strong>：现代浏览器默认 <code>SameSite=Lax</code>，跨站请求不带 Cookie；跨域携带 Cookie 还需 <code>withCredentials: true</code>（前端）+ <code>Access-Control-Allow-Credentials: true</code>（后端）+ Cookie 设 <code>SameSite=None; Secure</code>。</p><p><strong>深度补充</strong>：<code>SameSite</code> 三值——<code>Strict</code>（完全禁止跨站）、<code>Lax</code>（默认，顶层导航 GET 携带）、<code>None</code>（允许，但必须 <code>Secure</code>）。SSO/嵌入第三方页面时常用 <code>SameSite=None; Secure</code>。</p><h3 id="q9-xss-是什么-怎么防" tabindex="-1">Q9. XSS 是什么？怎么防？ <a class="header-anchor" href="#q9-xss-是什么-怎么防" aria-label="Permalink to &quot;Q9. XSS 是什么？怎么防？&quot;">​</a></h3><p><strong>要点</strong>：XSS 是攻击者注入并执行恶意脚本。分三类——<strong>存储型</strong>（存入数据库，危害最大）、<strong>反射型</strong>（URL 参数回显）、<strong>DOM 型</strong>（前端 JS 直接插入）。防御：输出<strong>转义</strong>、输入校验、<code>Content-Security-Policy</code>（CSP）、<code>HttpOnly</code> Cookie。</p><p><strong>深度补充</strong>：<code>HttpOnly</code> 让 JS 无法读取 Cookie（防 cookie 窃取）；CSP 用 <code>script-src &#39;self&#39;</code> 白名单限制脚本来源。React 默认转义 JSX 插值，但 <code>dangerouslySetInnerHTML</code>、<code>v-html</code> 会绕过，必须对富文本做<strong>白名单过滤</strong>（如 DOMPurify）。</p><h3 id="q10-csrf-是什么-怎么防" tabindex="-1">Q10. CSRF 是什么？怎么防？ <a class="header-anchor" href="#q10-csrf-是什么-怎么防" aria-label="Permalink to &quot;Q10. CSRF 是什么？怎么防？&quot;">​</a></h3><p><strong>要点</strong>：CSRF 利用浏览器<strong>自动携带 Cookie</strong> 的特性，诱导用户已登录的站点发起恶意请求。防御：<strong>CSRF Token</strong>（服务端下发、提交时校验）、<code>SameSite</code> Cookie、校验 <code>Origin/Referer</code>、关键操作二次验证。</p><p><strong>深度补充</strong>：XSS 与 CSRF 区别——XSS 是&quot;信任了用户输入&quot;，CSRF 是&quot;信任了用户浏览器&quot;。用了 <code>SameSite=Lax/Strict</code> 后，多数 CSRF 场景已被浏览器默认抵挡，但同站点的 CSRF 仍需 Token。</p><h2 id="四、http-协议与实时通信" tabindex="-1">四、HTTP 协议与实时通信 <a class="header-anchor" href="#四、http-协议与实时通信" aria-label="Permalink to &quot;四、HTTP 协议与实时通信&quot;">​</a></h2><h3 id="q11-http-1-1、http-2、http-3-的区别" tabindex="-1">Q11. HTTP/1.1、HTTP/2、HTTP/3 的区别？ <a class="header-anchor" href="#q11-http-1-1、http-2、http-3-的区别" aria-label="Permalink to &quot;Q11. HTTP/1.1、HTTP/2、HTTP/3 的区别？&quot;">​</a></h3><p><strong>要点</strong>：HTTP/1.1 明文文本、队头阻塞、同域连接数受限（浏览器约 6 个）；HTTP/2 二进制分帧、<strong>多路复用</strong>（一个 TCP 连接并发多请求）、头部压缩（HPACK）、服务端推送，但仍有 <strong>TCP 层队头阻塞</strong>；HTTP/3 基于 <strong>QUIC（UDP）</strong>，消除 TCP 队头阻塞、0-RTT 建连、连接迁移。</p><p><strong>深度补充</strong>：HTTP/2 的多路复用解决了应用层队头阻塞，但丢包会让同一 TCP 连接的所有流等待（TCP 队头阻塞）；QUIC 把流独立，丢包只影响单流。HTTP/2 需 HTTPS（浏览器实现要求）。</p><h3 id="q12-websocket-与-sse-的区别" tabindex="-1">Q12. WebSocket 与 SSE 的区别？ <a class="header-anchor" href="#q12-websocket-与-sse-的区别" aria-label="Permalink to &quot;Q12. WebSocket 与 SSE 的区别？&quot;">​</a></h3><p><strong>要点</strong>：WebSocket 基于 <code>ws://</code>，<strong>全双工</strong>、双向通信，适合 IM/协同编辑；SSE 基于 HTTP，<strong>单向</strong>（服务器 → 客户端）、自动重连、文本流，适合推送通知/进度；两者都不受同源策略的读取限制（WebSocket 需服务端校验 Origin）。</p><p><strong>深度补充</strong>：SSE 相比 WebSocket 更轻（无需协议升级），但只能服务端推、只支持文本。AI 产品（#10）的<strong>流式输出</strong>常用 SSE 或 fetch + <code>ReadableStream</code> 实现。</p><h3 id="q13-如何做实时通信的断线重连与消息补偿" tabindex="-1">Q13. 如何做实时通信的断线重连与消息补偿？ <a class="header-anchor" href="#q13-如何做实时通信的断线重连与消息补偿" aria-label="Permalink to &quot;Q13. 如何做实时通信的断线重连与消息补偿？&quot;">​</a></h3><p><strong>要点</strong>：心跳保活（定时 <code>ping</code>/<code>pong</code> 检测死连接）；断线用<strong>指数退避</strong>重连（避免风暴）；重连成功后按<strong>最后一条消息 ID/序号</strong>拉取离线消息，实现补偿。</p><p><strong>深度补充</strong>：消息要有唯一 ID 与单调递增序号，服务端保留一段历史；客户端记录 <code>lastSeq</code>，重连后 <code>sync(lastSeq)</code>。这正是 #8 鹏开信息 IM 岗的核心考点（见 <a href="/frontend-kb-pages/network/im">IM 前端</a>）。</p><h2 id="五、存储方案" tabindex="-1">五、存储方案 <a class="header-anchor" href="#五、存储方案" aria-label="Permalink to &quot;五、存储方案&quot;">​</a></h2><h3 id="q14-cookie-localstorage-sessionstorage-indexeddb-对比" tabindex="-1">Q14. Cookie / localStorage / sessionStorage / IndexedDB 对比？ <a class="header-anchor" href="#q14-cookie-localstorage-sessionstorage-indexeddb-对比" aria-label="Permalink to &quot;Q14. Cookie / localStorage / sessionStorage / IndexedDB 对比？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Cookie</th><th>localStorage</th><th>sessionStorage</th><th>IndexedDB</th></tr></thead><tbody><tr><td>容量</td><td>约 4KB</td><td>约 5MB</td><td>约 5MB</td><td>数百 MB+</td></tr><tr><td>生命周期</td><td>可设过期</td><td>永久（除非清除）</td><td>关闭标签页即清</td><td>永久</td></tr><tr><td>随请求发送</td><td><strong>是</strong></td><td>否</td><td>否</td><td>否</td></tr><tr><td>同步/异步</td><td>同步</td><td>同步</td><td>同步</td><td>异步</td></tr><tr><td>存储类型</td><td>字符串</td><td>字符串</td><td>字符串</td><td>任意结构化</td></tr></tbody></table><p><strong>深度补充</strong>：Cookie 会自动附加到同源请求，是它最大的&quot;负担&quot;；localStorage <strong>同步</strong>，存大 JSON 会阻塞主线程（大屏/IM 大量数据改用 IndexedDB）。跨标签页同步可用 <code>storage</code> 事件或 <code>BroadcastChannel</code>。</p><h3 id="q15-localstorage-的性能坑" tabindex="-1">Q15. <code>localStorage</code> 的性能坑？ <a class="header-anchor" href="#q15-localstorage-的性能坑" aria-label="Permalink to &quot;Q15. `localStorage` 的性能坑？&quot;">​</a></h3><p><strong>要点</strong>：<code>localStorage</code> 是同步 API，读写大对象会阻塞主线程，导致卡顿/掉帧。</p><p><strong>深度补充</strong>：大数据（历史消息、图表缓存）用 IndexedDB（异步）；需要更快的会话级缓存可放在内存 + <code>sessionStorage</code>。敏感数据不要放 localStorage（XSS 可读），应放 <code>HttpOnly</code> Cookie。</p><h2 id="六、性能与监控" tabindex="-1">六、性能与监控 <a class="header-anchor" href="#六、性能与监控" aria-label="Permalink to &quot;六、性能与监控&quot;">​</a></h2><h3 id="q16-core-web-vitals-是哪三个指标" tabindex="-1">Q16. Core Web Vitals 是哪三个指标？ <a class="header-anchor" href="#q16-core-web-vitals-是哪三个指标" aria-label="Permalink to &quot;Q16. Core Web Vitals 是哪三个指标？&quot;">​</a></h3><p><strong>要点</strong>：<strong>LCP</strong>（最大内容绘制，加载性能）、<strong>INP</strong>（Interaction to Next Paint，交互响应性，2024 起替代 FID）、<strong>CLS</strong>（累积布局偏移，视觉稳定性）。目标：LCP &lt; 2.5s、INP &lt; 200ms、CLS &lt; 0.1。</p><p><strong>深度补充</strong>：LCP 优化——压缩/预加载首屏大图、<code>fetchpriority=&quot;high&quot;</code>、CDN、服务端渲染；CLS 优化——给图片/广告位预留尺寸、字体 <code>font-display: optional</code>、避免动态插入内容顶掉布局；INP 优化——减少长任务、拆包、用 <code>requestIdleCallback</code>。</p><h3 id="q17-首屏加载怎么优化" tabindex="-1">Q17. 首屏加载怎么优化？ <a class="header-anchor" href="#q17-首屏加载怎么优化" aria-label="Permalink to &quot;Q17. 首屏加载怎么优化？&quot;">​</a></h3><p><strong>要点</strong>：资源层面——代码分割（路由懒加载）、Tree-shaking、压缩（gzip/brotli）、CDN、HTTP/2；渲染层面——SSR/预渲染、骨架屏、关键 CSS 内联、图片懒加载/WebP、<code>preload/prefetch</code>。</p><p><strong>深度补充</strong>：用 <code>performance</code> API 或 Lighthouse 量化——TTFB（网络/服务端）、FCP、LCP 分别定位瓶颈。命中 A3 级&quot;性能优化（首屏/懒加载/渲染）&quot;（9 份 JD）。</p><h3 id="q18-前端如何做异常监控与上报" tabindex="-1">Q18. 前端如何做异常监控与上报？ <a class="header-anchor" href="#q18-前端如何做异常监控与上报" aria-label="Permalink to &quot;Q18. 前端如何做异常监控与上报？&quot;">​</a></h3><p><strong>要点</strong>：三类异常——JS 运行时错误（<code>window.onerror</code> / <code>error</code> 事件）、资源加载错误（<code>error</code> 事件捕获阶段）、未处理的 Promise 拒绝（<code>unhandledrejection</code>）。上报要点：采样、<code>navigator.sendBeacon</code>（不阻塞卸载）、错误去重、携带 sourcemap 还原堆栈。</p><p><strong>深度补充</strong>：还要补——接口错误（拦截 fetch/XHR）、白屏检测、性能指标上报（<code>PerformanceObserver</code>）。上报队列可做<strong>合并与批量</strong>，失败重试。这是 #3 腾讯外包&quot;监控 SDK/可观测体系&quot;的核心考点。</p><h3 id="q19-sendbeacon-与-fetch-keepalive-为什么适合埋点上报" tabindex="-1">Q19. <code>sendBeacon</code> 与 <code>fetch(keepalive)</code> 为什么适合埋点上报？ <a class="header-anchor" href="#q19-sendbeacon-与-fetch-keepalive-为什么适合埋点上报" aria-label="Permalink to &quot;Q19. `sendBeacon` 与 `fetch(keepalive)` 为什么适合埋点上报？&quot;">​</a></h3><p><strong>要点</strong>：它们能在页面<strong>卸载时</strong>可靠地把数据发出去且不阻塞跳转。<code>navigator.sendBeacon(url, data)</code> 适合小数据；<code>fetch(url, { keepalive: true })</code> 支持更大负载与自定义头。</p><p><strong>深度补充</strong>：普通 <code>XHR</code> 在卸载时可能被中断；<code>sendBeacon</code> 由浏览器排队保证送达。埋点 SDK 常用 <code>visibilitychange</code>/<code>pagehide</code> 触发上报。</p><h3 id="q20-http-请求层的常见设计" tabindex="-1">Q20. HTTP 请求层的常见设计？ <a class="header-anchor" href="#q20-http-请求层的常见设计" aria-label="Permalink to &quot;Q20. HTTP 请求层的常见设计？&quot;">​</a></h3><p><strong>要点</strong>：统一封装（baseURL、超时、鉴权头注入）、拦截器（请求加 token、响应统一错误处理/刷新 token）、错误分类（网络/超时/业务码）、取消（<code>AbortController</code>）、重试与并发控制。</p><p><strong>深度补充</strong>：401 自动刷新 token 需<strong>并发排队</strong>（刷新期间挂起其他请求，刷新后重放），并用队列防止 token 刷新风暴。详见 <a href="/frontend-kb-pages/network/http-layer">HTTP 与请求层设计</a>。</p><h3 id="q21-浏览器事件循环中渲染发生在哪一步" tabindex="-1">Q21. 浏览器事件循环中渲染发生在哪一步？ <a class="header-anchor" href="#q21-浏览器事件循环中渲染发生在哪一步" aria-label="Permalink to &quot;Q21. 浏览器事件循环中渲染发生在哪一步？&quot;">​</a></h3><p><strong>要点</strong>：每个宏任务执行完、<strong>微任务清空后</strong>，浏览器才会决定是否渲染（<code>requestAnimationFrame</code> 回调在这一步之前执行）。若主线程被长任务占满，渲染会被推迟，造成掉帧。</p><p><strong>深度补充</strong>：<code>requestAnimationFrame</code> 在<strong>下一次重绘前</strong>执行（约 60fps / 16.7ms 一次）。动画用 rAF 而非 <code>setTimeout</code> 才能对齐刷新；<code>requestIdleCallback</code> 在帧空闲时执行低优先级任务。</p><h2 id="面试要点" tabindex="-1">面试要点 <a class="header-anchor" href="#面试要点" aria-label="Permalink to &quot;面试要点&quot;">​</a></h2><ol><li><strong>输入 URL 到渲染？</strong> DNS → TCP/TLS → HTTP → 解析构建 DOM/CSSOM → 布局 → 绘制 → 合成；<code>&lt;script&gt;</code> 阻塞解析。</li><li><strong>重排 vs 重绘？</strong> 重排改几何、代价最大；重绘只改外观；<code>transform/opacity</code> 只走合成、不触发两者。</li><li><strong>强缓存 vs 协商缓存？</strong> 强缓存不发请求（<code>Cache-Control</code>）；协商缓存发请求问是否更新，未变返回 304（<code>ETag</code>）。</li><li><strong>跨域怎么答？</strong> 同源策略限制读取响应；CORS（含预检与凭证）、代理、postMessage、WebSocket 是主要方案。</li><li><strong>XSS vs CSRF？</strong> XSS 是&quot;信任了输入&quot;（注入脚本），CSRF 是&quot;信任了浏览器&quot;（诱导已登录请求）；分别用转义/CSP 与 Token/SameSite。</li><li><strong>HTTP/2 与 HTTP/3？</strong> HTTP/2 多路复用仍受 TCP 队头阻塞；HTTP/3 用 QUIC（UDP）消除之，支持 0-RTT。</li><li><strong>核心指标？</strong> LCP（加载）、INP（交互）、CLS（稳定）。</li><li><strong>异常监控三类？</strong> <code>onerror</code>、资源错误、<code>unhandledrejection</code>；用 <code>sendBeacon</code> 可靠上报 + sourcemap 还原。</li></ol>',75)])])}const S=e(d,[["render",n]]);export{p as __pageData,S as default};
